  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 The Nature of Earth Science and Maps$j$, $j${"readings": [{"title": "Job 38 (King James Version)", "url": "/portal/bible/Job/38"}], "body": "Earth science is the study of our home planet and its place in space. Job 38:4 asks, Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding. God is the Creator of the earth, and earth scientists study the way He ordered it. Psalm 111:2 says, The works of the LORD are great, sought out of all them that have pleasure therein.\n\nEarth science has four main branches. Geology studies the solid Earth, its rocks, landforms and history. Meteorology studies the atmosphere and weather. Oceanography studies the oceans. Astronomy studies space, including the Sun, Moon, planets and stars. Earth scientists observe, measure and test, and they build models, which are simplified pictures or equations that help explain how a system works.\n\nEarth works as a set of connected systems. The geosphere is the solid Earth. The hydrosphere is all the water. The atmosphere is the blanket of air. The biosphere is all living things. A volcano, for example, can change the land, the air and the lives of people at the same time.\n\nMaps help us find places. Latitude measures distance north or south of the equator, which is 0 degrees, up to 90 degrees at the poles. Longitude measures distance east or west of the prime meridian, which is 0 degrees, up to 180 degrees. Pompano Beach is at about 26 degrees north and 80 degrees west. A map scale tells how a distance on the map compares with the real distance. If 1 centimeter stands for 10 kilometers, then 4.5 centimeters stands for 45 kilometers.\n\nA topographic map shows the shape of the land with contour lines. Each line joins points of equal elevation, and the contour interval is the change in elevation between lines. Lines that are close together show a steep slope. Lines that are far apart show a gentle slope. Closed circles show hills, and a V shape that points uphill shows a stream valley. A GPS receiver finds your position by timing signals from satellites.\n\nYour task: (1) Name the four branches of Earth science and the four Earth systems. (2) Give the latitude and longitude of a place. (3) Tell what close contour lines mean on a topographic map.\n\nFlorida standards: SC.912.E.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.5", "script": "Welcome back. Listen, Job 38:4 asks, Where wast thou when I laid the foundations of the earth? declare, if thou hast understanding. God is the Creator of the earth, and earth scientists study the way He ordered it.\n\nNow watch this. Earth science has four main branches. Geology studies the solid Earth. Meteorology studies the atmosphere and weather. Oceanography studies the oceans. Astronomy studies space. Earth also works as four connected systems: the geosphere, the hydrosphere, the atmosphere and the biosphere. A volcano can change all four at once.\n\nLook at maps. Latitude measures north or south of the equator, from 0 to 90 degrees. Longitude measures east or west of the prime meridian, from 0 to 180 degrees. Pompano Beach is at about 26 degrees north and 80 degrees west. If 1 centimeter on the map stands for 10 kilometers, then 4.5 centimeters stands for 45 kilometers.\n\nA topographic map uses contour lines to show the shape of the land. Lines close together mean a steep slope. Lines far apart mean a gentle slope.\n\nYour task is to name the branches and systems, give a latitude and longitude and read contour lines. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 The Nature of Earth Science and Maps$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Earth, Moon and Sun$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Earth moves in two main ways. Genesis 1:14 says, And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and for years. Rotation is the spinning of Earth on its axis, once about every 24 hours, and it causes day and night. Revolution is the trip of Earth around the Sun, which takes about 365 and one fourth days. We add a leap day every four years to keep the calendar in step.\n\nEarth's axis is tilted about 23.5 degrees. The tilt, not the distance from the Sun, causes the seasons. When the Northern Hemisphere leans toward the Sun, it gets more direct sunlight and longer days, and it is summer there. When it leans away, it is winter. The solstices, near June 21 and December 21, are the longest and shortest days. The equinoxes, near March 20 and September 22, have nearly equal day and night. Earth is actually closest to the Sun in early January, about 147 million kilometers away, and farthest in July, about 152 million kilometers.\n\nThe Moon orbits Earth about every 27.3 days, and it always shows us the same face. We see the Moon because it reflects sunlight, and the phases come from how much of the lit half we can see. The cycle from one new moon to the next takes about 29.5 days. The Moon grows from new moon to first quarter to full moon, which is waxing, and then shrinks back, which is waning.\n\nAn eclipse happens when Earth, the Moon and the Sun line up. In a solar eclipse the Moon passes between the Sun and Earth, and it happens at new moon. In a lunar eclipse Earth passes between the Sun and the Moon, and it happens at full moon. Never look directly at the Sun, even during an eclipse, without proper eclipse glasses.\n\nTides are the rise and fall of the ocean. The Moon's gravity pulls on the water most, and the Sun's gravity adds to it. Spring tides, the highest and lowest, happen at new and full moon. Neap tides, the smallest, happen at the quarter moons.\n\nYour task: (1) Tell what causes day and night and the seasons. (2) Explain the Moon's phases and eclipses. (3) Explain spring and neap tides.\n\nFlorida standards: SC.912.E.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.5", "script": "Welcome back. Listen, Genesis 1:14 says, And God said, Let there be lights in the firmament of the heaven to divide the day from the night; and let them be for signs, and for seasons, and for days, and for years.\n\nNow watch this. Rotation is Earth spinning once about every 24 hours, and it makes day and night. Revolution is Earth going around the Sun in about 365 and one fourth days. Earth's axis is tilted about 23.5 degrees, and that tilt causes the seasons. Many people think summer comes when Earth is closest to the Sun. But Earth is closest in early January, so distance is not the cause.\n\nLook at the Moon. It orbits Earth about every 27.3 days, and the cycle of phases takes about 29.5 days. We see the lit part reflecting sunlight. A solar eclipse happens at new moon when the Moon blocks the Sun. A lunar eclipse happens at full moon when Earth's shadow falls on the Moon. Never look directly at the Sun.\n\nTides come mainly from the Moon's gravity, with help from the Sun. Spring tides happen at new and full moon. Neap tides happen at the quarter moons.\n\nYour task is to explain day, night and seasons, phases and eclipses, and tides. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Earth, Moon and Sun$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 The Solar System$j$, $j${"readings": [{"title": "Psalm 8 (King James Version)", "url": "/portal/bible/Psalms/8"}], "body": "The solar system is the Sun and everything that orbits it. Psalm 8:3 says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained. The Sun holds about 99.8 percent of the mass of the solar system, and its gravity keeps the planets in their orbits. Each planet moves in an ellipse, a slightly flattened circle, and planets closer to the Sun move faster.\n\nDistances in the solar system are large, so astronomers use the astronomical unit, abbreviated AU, which is the average distance from Earth to the Sun, about 150 million kilometers. Mercury is about 0.4 AU from the Sun, Jupiter about 5.2 AU and Neptune about 30 AU. Sunlight takes about 8 minutes to reach Earth and more than 4 hours to reach Neptune.\n\nThe four inner planets, Mercury, Venus, Earth and Mars, are small, rocky terrestrial planets. Venus has a thick carbon dioxide atmosphere and is the hottest planet, about 465 degrees Celsius. Mars is cold and dry, with the tallest volcano in the solar system, Olympus Mons. The four outer planets are much larger. Jupiter and Saturn are gas giants made mostly of hydrogen and helium. Uranus and Neptune are ice giants. Jupiter has a storm called the Great Red Spot that is larger than Earth, and Saturn is known for its bright rings.\n\nBetween Mars and Jupiter lies the asteroid belt, a region of rocky bodies. Beyond Neptune is the Kuiper belt, home to icy bodies and dwarf planets such as Pluto, which was reclassified as a dwarf planet in 2006. Comets are balls of ice and dust that grow glowing tails when they near the Sun. A meteoroid is a small piece of rock in space. It is called a meteor when it burns up in the atmosphere and a meteorite if it lands on the ground.\n\nEarth is the only known planet that has liquid water on its surface, a protective atmosphere and life. Humans first walked on the Moon in 1969 during the Apollo 11 mission. Space exploration continues with robotic probes and rovers.\n\nYour task: (1) Name the planets in order and group them. (2) Explain what an astronomical unit is. (3) Tell the difference between an asteroid, a comet and a meteor.\n\nFlorida standards: SC.912.E.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.5", "script": "Welcome back. Listen, Psalm 8:3 says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained.\n\nNow watch this. The solar system is the Sun and everything that orbits it. The Sun holds about 99.8 percent of the mass, and its gravity holds the planets in elliptical orbits. We measure distance in astronomical units. One AU is the distance from Earth to the Sun, about 150 million kilometers. Sunlight takes about 8 minutes to reach Earth.\n\nLook at the planets. Mercury, Venus, Earth and Mars are small and rocky. Jupiter and Saturn are gas giants. Uranus and Neptune are ice giants. Venus is the hottest planet, about 465 degrees Celsius. Mars has the tallest volcano, Olympus Mons.\n\nThe asteroid belt lies between Mars and Jupiter. The Kuiper belt lies beyond Neptune, and Pluto is a dwarf planet. Comets are balls of ice and dust with glowing tails. A meteor is a streak of light as a rock burns up in our atmosphere.\n\nEarth is the only known planet with liquid water on the surface and life.\n\nYour task is to order and group the planets, explain the AU and tell asteroid, comet and meteor apart. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 The Solar System$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Stars, Galaxies and the Universe$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "Stars are huge balls of hot gas that give off light. Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork. Isaiah 40:26 says that God calleth them all by names. People have studied the stars since ancient times.\n\nA star shines because of nuclear fusion in its core, where hydrogen nuclei join to make helium and release enormous energy. The Sun is a medium sized star, and its core is about 15 million kelvins. Stars differ in size, temperature, color and brightness. Hot stars look blue or white, and cooler stars look red. Astronomers find what stars are made of by splitting their light into a spectrum and studying the dark and bright lines.\n\nDistances between stars are so great that astronomers use the light year, the distance light travels in one year, about 9.5 trillion kilometers. The nearest star beyond the Sun, Proxima Centauri, is about 4.2 light years away. When you look at a distant star, you see light that left it long ago.\n\nA star has a life cycle. It begins in a cloud of gas and dust called a nebula and becomes a main sequence star while it fuses hydrogen. A star like the Sun will later swell into a red giant and end as a small, dense white dwarf. A star much more massive than the Sun ends in a supernova, a huge explosion, and leaves a neutron star or a black hole.\n\nStars gather into galaxies, vast systems of stars, gas and dust held together by gravity. Our galaxy, the Milky Way, is a spiral galaxy that holds hundreds of billions of stars, and the Sun lies about 26,000 light years from its center. There are billions of other galaxies.\n\nObservations show that distant galaxies are moving away from us, which means the universe is expanding. The leading scientific model, the big bang theory, estimates that the universe began about 13.8 billion years ago. Believers agree that God created the universe, and thoughtful Christians differ on how to read the details of Genesis and the age of the universe. Science describes how the universe behaves, and Scripture tells us who made it and why.\n\nYour task: (1) Explain how a star makes energy. (2) Define a light year. (3) Order the stages in the life of a star like the Sun.\n\nFlorida standards: SC.912.E.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.E.5", "script": "Welcome back. Listen, Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork.\n\nNow watch this. A star shines because of nuclear fusion in its core. Hydrogen nuclei join to make helium and release huge energy. The Sun is a medium sized star with a core of about 15 million kelvins. Hot stars look blue or white. Cooler stars look red.\n\nDistances are huge, so we use the light year, the distance light travels in one year, about 9.5 trillion kilometers. The nearest star beyond the Sun is about 4.2 light years away.\n\nLook at the life of a star. It begins in a nebula, becomes a main sequence star, swells into a red giant and ends as a white dwarf. A far more massive star ends in a supernova and leaves a neutron star or a black hole.\n\nStars gather in galaxies. Our galaxy is the Milky Way, a spiral with hundreds of billions of stars. Distant galaxies are moving away from us, so the universe is expanding. Believers agree that God created the universe, and thoughtful Christians differ on how to read the details of Genesis. Science tells how the universe behaves, and Scripture tells us who made it and why.\n\nYour task is to explain how stars make energy, define a light year and order the stages of a star's life. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Stars, Galaxies and the Universe$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Earth in Space$j$, $j${"prompt": "Write a report of at least 250 words on Earth in space. Use complete sentences, show every calculation and label each part. Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork.\n\nPart 1: Name the four branches of Earth science and the four Earth systems, and give an example of how two systems interact. Give the approximate latitude and longitude of Pompano Beach.\nPart 2: On a map, 2 centimeters stand for 25 kilometers. Find the real distance for 7 centimeters. Explain what close contour lines show on a topographic map.\nPart 3: Explain why Earth has seasons, why distance from the Sun is not the cause, and what causes day and night.\nPart 4: Describe the phases of the Moon, explain how a solar eclipse differs from a lunar eclipse, and explain spring tides and neap tides.\nPart 5: Name the planets in order from the Sun, group them, and explain the astronomical unit and the light year. Describe how a star like the Sun makes energy and how it ends, and tell what Psalm 19:1 teaches about the heavens.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 20 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Earth in Space$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: The Heavens Declare$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time you looked at the night sky, the Moon or a sunrise and what you thought, (2) explains in your own words one thing you learned about Earth, the Moon or the Sun, (3) explains how the size and order of the universe point to the greatness of God, and (4) connects your answer to Psalm 19:1, Genesis 1:14 or Job 38:4. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a believer enjoy studying space with both wonder and humility? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: The Heavens Declare$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: The Nature of Earth Science and Maps$j$, $j${"questions": [{"q": "The branch of Earth science that studies the atmosphere and weather is:", "options": ["Oceanography", "Geology", "Meteorology", "Astronomy"]}, {"q": "All of the water on Earth makes up the:", "options": ["Atmosphere", "Hydrosphere", "Geosphere", "Biosphere"]}, {"q": "Latitude measures distance:", "options": ["From the center of Earth", "North or south of the equator", "East or west of the prime meridian", "Above sea level"]}, {"q": "On a topographic map, contour lines that are very close together show:", "options": ["A body of water", "A gentle slope", "A steep slope", "A flat plain"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Nature of Earth Science and Maps$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,2}'::int[], array[$j$Meteorology studies the atmosphere and weather.$j$,$j$The hydrosphere is Earth's water.$j$,$j$Latitude lines run east and west and measure north or south position.$j$,$j$Close lines mean the elevation changes quickly.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: The Nature of Earth Science and Maps$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Earth, Moon and Sun$j$, $j${"questions": [{"q": "Earth's seasons are caused mainly by:", "options": ["Earth's distance from the Sun", "The tilt of Earth's axis", "The speed of Earth's rotation", "The Moon's phases"]}, {"q": "Earth's rotation causes:", "options": ["Eclipses", "The seasons", "The phases of the Moon", "Day and night"]}, {"q": "A solar eclipse happens when the:", "options": ["Moon is full", "Moon passes between the Sun and Earth", "Sun passes between Earth and the Moon", "Earth passes between the Sun and the Moon"]}, {"q": "The highest and lowest tides, called spring tides, happen at:", "options": ["New moon and full moon", "Only in spring", "Only during eclipses", "First and third quarter moons"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Earth, Moon and Sun$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,0}'::int[], array[$j$The 23.5 degree tilt changes how directly sunlight strikes each hemisphere.$j$,$j$One spin takes about 24 hours.$j$,$j$The Moon blocks sunlight at new moon.$j$,$j$The Sun and Moon pull together at new and full moon.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Earth, Moon and Sun$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: The Solar System$j$, $j${"questions": [{"q": "Which planets are terrestrial planets?", "options": ["Mercury, Venus, Earth and Mars", "Pluto and Ceres", "Uranus and Neptune", "Jupiter and Saturn"]}, {"q": "An astronomical unit is about:", "options": ["1 million kilometers", "9.5 trillion kilometers", "150 million kilometers", "384,000 kilometers"]}, {"q": "The asteroid belt lies between the orbits of:", "options": ["Mars and Jupiter", "Saturn and Uranus", "Neptune and Pluto", "Earth and Mars"]}, {"q": "The hottest planet in the solar system is:", "options": ["Jupiter", "Mars", "Venus", "Mercury"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Solar System$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2}'::int[], array[$j$The four inner planets are small and rocky.$j$,$j$One AU is the average Earth to Sun distance.$j$,$j$Rocky bodies orbit in the gap between Mars and Jupiter.$j$,$j$Venus has a thick carbon dioxide atmosphere that traps heat.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Solar System$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Stars, Galaxies and the Universe$j$, $j${"questions": [{"q": "A star produces energy by:", "options": ["Burning like a campfire", "Reflecting light from other stars", "Nuclear fusion in its core", "Chemical reactions on its surface"]}, {"q": "A light year is a unit of:", "options": ["Time", "Brightness", "Distance", "Temperature"]}, {"q": "Our home galaxy is called the:", "options": ["Oort cloud", "Milky Way", "Kuiper belt", "Andromeda"]}, {"q": "Which is the correct order for a star like the Sun?", "options": ["Main sequence star, nebula, white dwarf, red giant", "Red giant, nebula, white dwarf, main sequence star", "Nebula, main sequence star, red giant, white dwarf", "White dwarf, red giant, main sequence star, nebula"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Stars, Galaxies and the Universe$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,2}'::int[], array[$j$Hydrogen fuses into helium and releases energy.$j$,$j$It is the distance light travels in one year.$j$,$j$The Milky Way is a spiral galaxy.$j$,$j$A star like the Sun ends as a white dwarf.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Stars, Galaxies and the Universe$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Earth in Space$j$, $j${"questions": [{"q": "The four main Earth systems are the geosphere, hydrosphere, atmosphere and:", "options": ["Stratosphere", "Lithosphere", "Troposphere", "Biosphere"]}, {"q": "A map scale says 1 centimeter equals 10 kilometers. A distance of 6 centimeters on the map equals:", "options": ["600 kilometers", "6 kilometers", "60 kilometers", "16 kilometers"]}, {"q": "Earth takes about how long to complete one revolution around the Sun?", "options": ["27.3 days", "29.5 days", "24 hours", "365 and one fourth days"]}, {"q": "A lunar eclipse occurs at:", "options": ["New moon", "Full moon", "First quarter", "Third quarter"]}, {"q": "Neap tides happen when the Sun and Moon are:", "options": ["Both on the same side of Earth", "At right angles to each other as seen from Earth", "Not pulling at all", "In a straight line with Earth"]}, {"q": "Which planet is a gas giant?", "options": ["Venus", "Mercury", "Saturn", "Mars"]}, {"q": "Light from the Sun takes about how long to reach Earth?", "options": ["8 days", "8 seconds", "8 minutes", "8 hours"]}, {"q": "The universe is expanding, as shown by:", "options": ["The Sun getting smaller", "Distant galaxies moving away from us", "Planets changing orbits", "The Moon moving away"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Earth in Space$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,1,1,2,2,1}'::int[], array[$j$The biosphere is all living things.$j$,$j$6 times 10 equals 60.$j$,$j$A revolution is one trip around the Sun.$j$,$j$Earth's shadow falls on the Moon when it is full.$j$,$j$At the quarter moons their pulls partly cancel.$j$,$j$Saturn is made mostly of hydrogen and helium.$j$,$j$The Sun is about 150 million kilometers away.$j$,$j$Observations of galaxies show the expansion.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Earth in Space$j$ on conflict (item_id) do nothing;
